import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class RestrictByOneTypeOfResultVisitor_caseObjectType_TriageGen0Test {

    @Spy
    private com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor visitor;

    private ObjectType mockObjectType;
    private JSType mockFunctionType;
    private JSType mockConstructorType;

    @Before
    public void setUp() {
        mockObjectType = mock(ObjectType.class);
        mockFunctionType = mock(FunctionType.class);
        mockConstructorType = mock(JSType.prototype);

        // Default setup for the visitor fields/methods used via Spy or Mock
        // Since we cannot easily inject private fields 'value' and 'resultEqualsValue' 
        // if they are private, we assume the visitor is a Spy or we use reflection/mocking 
        // for the internal logic if necessary. 
        // However, based on the provided code, 'value' and 'resultEqualsValue' are accessible within the class.
    }

    /**
     * Test Path 1: value is "function" AND resultEqualsValue is true AND ctorType is subtype of type
     */
    @Test
    public void testCaseObjectType_ValueFunction_ResultEqualsValueTrue_IsSubtype() {
        // Setup internal state via reflection if they are private, 
        // but here we simulate the logic through the spy/mock context.
        // Note: In a real scenario, we'd use reflection to set 'value' and 'resultEqualsValue'.
        setInternalState("value", "function");
        setInternalState("resultEqualsValue", true);

        when(visitor.getNativeType(any())).thenReturn(mockConstructorType);
        when(mockConstructorType.isSubtype(mockObjectType)).thenReturn(true);

        JSType result = visitor.caseObjectType(mockObjectType);

        assertEquals(mockConstructorType, result);
    }

    /**
     * Test Path 2: value is "function" AND resultEqualsValue is true AND ctorType is NOT subtype of type
     */
    @Test
    public void testCaseObjectType_ValueFunction_ResultEqualsValueTrue_NotSubtype() {
        setInternalState("value", "function");
        setInternalState("resultEqualsValue", true);

        when(visitor.getNativeType(any())).thenReturn(mockConstructorType);
        when(mockConstructorType.isSubtype(mockObjectType)).thenReturn(false);

        JSType result = visitor.caseObjectType(mockObjectType);

        assertNull(result);
    }

    /**
     * Test Path 3: value is "function" AND resultEqualsValue is false
     */
    @Test
    public void testCaseObjectType_ValueFunction_ResultEqualsValueFalse() {
        setInternalState("value", "function");
        setInternalState("resultEqualsValue", false);

        // getNativeType should still be called based on code structure
        when(visitor.getNativeType(any())).thenReturn(mockConstructorType);

        JSType result = visitor.caseObjectType(mockObjectType);

        assertNull(result);
    }

    /**
     * Test Path 4: value is NOT "function" AND matchesExpectation("object") is true
     */
    @Test
    public void testCaseObjectType_ValueNotFunction_MatchesExpectationTrue() {
        setInternalState("value", "not-function");

        // We need to mock the protected method matchesExpectation
        when(visitor.matchesExpectation("object")).thenReturn(true);

        JSType result = visitor.caseObjectType(mockObjectType);

        assertEquals(mockObjectType, result);
    }

    /**
     * Test Path 5: value is NOT "function" AND matchesExpectation("object") is false
     */
    @Test
    public void testCaseObjectType_ValueNotFunction_MatchesExpectationFalse() {
        setInternalState("value", "not-function");

        when(visitor.matchesExpectation("object")).thenReturn(false);

        JSType result = visitor.caseObjectType(mockObjectType);

        assertNull(result);
    }

    // Helper to access private fields for testing purposes
    private void setInternalState(String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = visitor.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(visitor, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    // Helper for Mockito any()
    private Object any() {
        return org.mockito.ArgumentMatchers.any();
    }
}
